#!/usr/bin/env bash
# Run in the existing MaxPlayer IntelliJ repository root. Default: apply.
set -euo pipefail
command -v python3 >/dev/null || { echo 'Python 3 is required'; exit 1; }
python3 - "$@" <<'AAB_REPO_FIX_PY'
import pathlib,subprocess,sys,json,base64,hashlib,datetime,os,tempfile
PAYLOAD = ''
def fail(message):
 print('STOP: '+message,file=sys.stderr);sys.exit(1)
mode=sys.argv[1] if len(sys.argv)==2 else '--apply' if len(sys.argv)==1 else ''
if mode not in ['--check','--apply','--verify']:fail('Use no argument (apply), --check, --apply or --verify.')
try:root=pathlib.Path(subprocess.check_output(['git','rev-parse','--show-toplevel'],stderr=subprocess.DEVNULL).decode().strip()).resolve()
except Exception:fail('Run from the existing MaxPlayer Git repository root.')
if pathlib.Path.cwd().resolve()!=root:fail('Run from your existing repository root.')
if not (root/'pubspec.yaml').is_file() or 'name: maxplayer' not in (root/'pubspec.yaml').read_text():fail('Not the MaxPlayer repository.')
entries=json.loads(base64.b64decode(PAYLOAD));changes=[]
def read(rel):
 p=root/rel
 for parent in [p,*p.parents]:
  if parent==root:break
  if parent.is_symlink():fail('Symlink not allowed: '+rel)
 if p.exists() and not p.is_file():fail('Not a file: '+rel)
 return p.read_bytes() if p.exists() else None
def sha(data):return hashlib.sha256(data).hexdigest() if data is not None else None
for e in entries:
 data=base64.b64decode(e['data'])
 if sha(data)!=e['after']:fail('Payload corruption: '+e['path'])
 old=read(e['path']);current=sha(old)
 if current==e['after']:continue
 if mode=='--verify':fail('File does not match update: '+e['path'])
 if current!=e['before']:fail('Unrecognized edits in '+e['path']+'. No files changed; do not overwrite your work.')
 changes.append((e['path'],old,data))
if mode=='--verify':print('VERIFIED: both update files match.');sys.exit(0)
if mode=='--check':print('CHECK PASSED: '+str(len(changes))+' files need update; nothing written.');sys.exit(0)
if not changes:print('Already applied. No files changed.');sys.exit(0)
backup=pathlib.Path(subprocess.check_output(['git','rev-parse','--git-path','aab-repository-fix-backups']).decode().strip())
if not backup.is_absolute():backup=root/backup
backup=backup/datetime.datetime.now(datetime.timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');backup.mkdir(parents=True)
for rel,old,data in changes:
 if old is not None:
  p=backup/rel;p.parent.mkdir(parents=True,exist_ok=True);p.write_bytes(old)
(backup/'manifest.json').write_text(json.dumps([{'path':r,'existed':o is not None} for r,o,d in changes]))
def replace(rel,data):
 p=root/rel
 if data is None:p.unlink(missing_ok=True);return
 p.parent.mkdir(parents=True,exist_ok=True)
 with tempfile.NamedTemporaryFile(dir=p.parent,delete=False) as f:f.write(data);tmp=f.name
 os.chmod(tmp,0o644);os.replace(tmp,p)
written=[]
try:
 for rel,old,data in changes:
  if read(rel)!=old:raise RuntimeError('File changed during apply: '+rel)
  replace(rel,data);written.append((rel,old))
 for e in entries:
  if sha(read(e['path']))!=e['after']:raise RuntimeError('Verification failed: '+e['path'])
except BaseException:
 for rel,old in reversed(written):replace(rel,old)
 raise
print('APPLIED and verified: AAB workflow + Gradle repository init script.')
print('Backup: '+str(backup))
print('No app/version/signing/Windows changes. No local build or push performed.')
AAB_REPO_FIX_PY
